def q(v): return 'null' if v is None else "'" + str(v).replace("'", "''") + "'"
rows = []
for (fid, ing, ctype, tag, tier, disc, fact, word, cite, url) in F:
    status = 'blocked' if tag == 'DNU' else 'approved'
    placement = 'any' if tag == 'SS' else 'caption'
    slide = word if tag == 'SS' else None
    safe = word
    notes = f'research library 2026-11 · {fid} · {tag}'
    rows.append(f"({q(CLIENT)}, null, {q(ctype)}, {q(fact)}, {q(safe)}, {q(slide)}, {q(status)}, {'true' if disc else 'false'}, 'research', {q(url)}, {q(notes)}, {q(ing)}, {q(cite)}, {q(tier)}, {q(placement)})")
sql = """-- Research library (deep research 2026-11-10): verified education + study facts. Generated by db/research_library_2026_11.py
-- SS -> approved (slide wording) · CO -> approved, caption only · DNU -> blocked claim forms. Re-runnable: rows from this batch are replaced.
delete from approved_facts where client_id = '%s' and notes like 'research library 2026-11 · %%';
insert into approved_facts (client_id, product_slug, claim_type, claim_text, safe_wording, slide_wording, status, needs_disclaimer,
                            source, source_ref, notes, ingredient, citation, tier, placement)
values
%s;
select status, placement, count(*) from approved_facts where notes like 'research library 2026-11 · %%' group by 1, 2 order by 1, 2;
""" % (CLIENT, ',\n'.join(rows))
